# test_ingestion_loader_txt_md.py - Tests for load_text_file() (.txt and .md)
# Code: English
# Comments: English
# Code generated by Claude. Made sure I understand it.

#
# All text is written inside the tests as bytes, so no files on disk are needed.
# The loader gets bytes and not a path because that is what POST /upload receives.

import pytest

from study_buddy.ingestion.loaders.text import load_text_file


# A .txt becomes one Document with one Section and no place
def test_txt_becomes_document():
    doc = load_text_file("notes.txt", b"Hello RAG")

    assert doc.source_type == "txt"
    assert len(doc.sections) == 1
    assert doc.sections[0].text == "Hello RAG"
    assert doc.sections[0].source_location is None


# The # heading is part of the text, the loader does not split on headings yet
def test_md_becomes_document():
    doc = load_text_file("week1.md", b"# Week 1\nSome text")

    assert doc.source_type == "md"
    assert doc.sections[0].text == "# Week 1\nSome text"


# Document.source_type only accepts lowercase, so the loader must lowercase it
@pytest.mark.parametrize(
    "filename, expected",
    [("NOTES.TXT", "txt"), ("a.Md", "md")],
)
def test_suffix_case_does_not_matter(filename, expected):
    doc = load_text_file(filename, b"Hello")

    assert doc.source_type == expected


# The filename is kept exactly as given (decision D5)
def test_filename_is_kept():
    doc = load_text_file("Week1.MD", b"Hello")

    assert doc.filename == "Week1.MD"


# Å, ä, ö, é and Japanese must survive the trip from bytes to text
def test_non_ascii_text_survives():
    text = "å ä ö é 日本"

    doc = load_text_file("notes.txt", text.encode("utf-8"))

    assert doc.sections[0].text == text


# The loader never guesses, so another suffix or no suffix is refused (D3)
@pytest.mark.parametrize("filename", ["slides.pdf", "README"])
def test_unknown_suffix_is_refused(filename):
    with pytest.raises(ValueError, match="expected a .txt or .md"):
        load_text_file(filename, b"Hello")


# 0xFF can never start a UTF-8 character, so these bytes are not text (D4)
def test_invalid_utf8_is_refused():
    with pytest.raises(ValueError, match="UTF-8"):
        load_text_file("notes.txt", b"\xff\xfe\x00")


# An empty file, or one with only spaces and new lines, gives no chunks (D6)
@pytest.mark.parametrize("data", [b"", b"  \n "])
def test_empty_file_is_refused(data):
    with pytest.raises(ValueError, match="empty"):
        load_text_file("notes.txt", data)


# Windows new lines (\r\n) become \n so the chunker can split on "\n\n" (D8)
def test_windows_line_endings_become_newlines():
    doc = load_text_file("notes.txt", b"line one\r\n\r\nline two")

    assert doc.sections[0].text == "line one\n\nline two"
